def find_similar_users(user_id, user_ratings):
  user_vector = user_ratings[user_id]
  similarities = {}
  for other_id, other_vector in user_ratings.items():
    if other_id != user_id:
      sim = cosine_similarity([user_vector], [other_vector])[0][0]
      similarities[other_id] = sim
  return sorted(similarities.items(), key=lambda x: x[1], reverse=True)

def generate_learning_path(user_knowledge, goal, duration_weeks):
  topics = rank_topics_by_difficulty(goal)
  weeks_per_topic = duration_weeks / len(topics)
  path = []
  for topic in topics:
    path.append({
      'topic': topic,
      'duration': weeks_per_topic,
      'difficulty': estimate_difficulty(topic, user_knowledge)
    })
  return path

